static const uint16_t *f16_lookup(uint32_t cp) {
    if (cp >= F16_BASE && cp < F16_BASE + F16_SPAN) {
        uint8_t i = F16_INDEX[cp - F16_BASE];
        return i == F16_NONE ? NULL : F16_GLYPHS[i];
    }
    uint32_t lo = 0, hi = F16_N_EXTRA;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (F16_EXTRA_CP[mid] == cp) return F16_GLYPHS[F16_EXTRA_SLOT[mid]];
        if (F16_EXTRA_CP[mid] < cp) lo = mid + 1; else hi = mid;
    }
    return NULL;
}

#endif
